/*
 * ps5-native-app-boilerplate - Application symbol visibility policy.
 * Copyright (C) 2026 BlackBearReloaded
 * SPDX-License-Identifier: GPL-3.0-or-later
 *
 * Keeps replacement C++ allocation operators internal to the executable, and
 * the --wrap replacements too: libc's stubs define the wrapped names
 * themselves, and lld exported __wrap_getcwd to interpose on them, which the
 * native converter refuses (a title publishes no exports).
 */

{
    local:
        _Zn*;
        _Zd*;
        __wrap_*;
};
